// Read registers 217 and 688
const reads = [
    { name: 'lowBatteryThreshold', address: 217, quantity: 1 },
    { name: 'currentSoc', address: 688, quantity: 1 }
];

const messages = reads.map(r => ({
    payload: {
        fc: 3,
        unitid: 1,
        address: r.address,
        quantity: r.quantity
    },
    readName: r.name,
    registerAddress: r.address
}));

return [messages];

const flowKey = 'low_soc_reads';
let collected = flow.get(flowKey) || {};
const expectedCount = 2;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data) || data.length < 1) {
    node.status({ fill: "red", shape: "dot", text: "Read failed: " + msg.readName });
    return null;
}

const value = data[0] || 0;

if (msg.readName === 'lowBatteryThreshold') {
    collected.lowBatteryCapacityPercent = value;
} else if (msg.readName === 'currentSoc') {
    collected.socPercent = value;
}

flow.set(flowKey, collected);

const collectedCount = Object.keys(collected).length;
node.status({ fill: "blue", shape: "dot", text: `Collected ${collectedCount}/${expectedCount}` });

if (collectedCount >= expectedCount) {
    flow.set(flowKey, null);
    msg.collectedData = collected;
    msg.payload = collected;
    return msg;
}

return null;

const data = msg.collectedData;

if (!data) {
    node.status({ fill: "red", shape: "dot", text: "No data" });
    return null;
}

const lowBatteryCapacityPercent = data.lowBatteryCapacityPercent;
const socPercent = data.socPercent;

// Get last sent step from flow context
let lastSentLowBatterySoc = flow.get("lastSentLowBatterySoc");

// First run: initialize lastSentLowBatterySoc
if (lastSentLowBatterySoc === null || lastSentLowBatterySoc === undefined) {
    lastSentLowBatterySoc = lowBatteryCapacityPercent;
    flow.set("lastSentLowBatterySoc", lastSentLowBatterySoc);
    node.status({ fill: "blue", shape: "dot", text: `Initialized: lastSent=${lastSentLowBatterySoc}` });
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";
const now = new Date().toISOString();

let shouldSend = false;
let alarm = null;

// Check if SOC is below threshold
if (socPercent < lowBatteryCapacityPercent) {
    // Calculate current step (5% increments, rounded down)
    const currentStep = Math.floor(socPercent / 5) * 5;

    // Only send if step decreased from last sent
    if (currentStep < lastSentLowBatterySoc) {
        shouldSend = true;
        flow.set("lastSentLowBatterySoc", currentStep);

        alarm = {
            code: "W11",
            vendorCode: null,
            severity: "WARNING",
            sourceDevice: "inverter",
            category: "battery",
            messageKey: "Battery_LowSOC",
            messageParams: {
                currentSocPercent: socPercent,
                thresholdPercent: lowBatteryCapacityPercent,
                triggeredAtStep: currentStep
            },
            firstOccurredUtc: now,
            lastOccurredUtc: now,
            occurrenceCount: 1
        };

        node.status({ 
            fill: "red", 
            shape: "dot", 
            text: `ALARM: SOC=${socPercent}% (step=${currentStep}, lastSent=${lastSentLowBatterySoc})` 
        });
    } else {
        node.status({ 
            fill: "yellow", 
            shape: "dot", 
            text: `SKIP: SOC=${socPercent}% (step=${currentStep} already sent)` 
        });
    }
} else {
    // SOC is above or equal to threshold - reset
    flow.set("lastSentLowBatterySoc", lowBatteryCapacityPercent);
    node.status({ 
        fill: "green", 
        shape: "dot", 
        text: `OK: SOC=${socPercent}% >= ${lowBatteryCapacityPercent}% (reset)` 
    });
}

// Build InverterAlarmState format
const state = {
    kind: "InverterAlarmState",
    timestampUtc: now,
    version: 1,
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,

    runStateRaw: null,
    commBoardFaultRaw: null,

    warningWord1Raw: null,
    warningWord2Raw: null,

    faultWord1Raw: null,
    faultWord2Raw: null,
    faultWord3Raw: null,
    faultWord4Raw: null,

    workFlagTripData: null,

    activeAlarms: alarm ? [alarm] : []
};

msg.payload = state;
msg.state = state;
msg.hasAlarms = alarm !== null;

return msg;

// Only send to ThingsBoard if there is an alarm
if (msg.hasAlarms) {
    node.status({ fill: "red", shape: "dot", text: "Sending LOW SOC alarm" });
    return msg;
}

node.status({ fill: "green", shape: "dot", text: "No alarm - skipped" });
return null;

flow.set("lastSentLowBatterySoc", null);
node.status({ fill: "green", shape: "dot", text: "Reset complete" });
msg.payload = "lastSentLowBatterySoc reset to null";
return msg;
